    assert item.qualifies_for_bulk_discount()


def test_qualifies_for_bulk_discount_quantity_11():
    item = LineItem("apple", Decimal("10.00"), 11)
    assert item.qualifies_for_bulk_discount()


def test_calculate_bulk_discount_non_qualifying():
    item = LineItem("apple", Decimal("10.00"), 9)
    assert item.calculate_bulk_discount() == Decimal("0.00")


def test_calculate_bulk_discount_qualifying():
    item = LineItem("apple", Decimal("10.00"), 10)
    assert item.calculate_bulk_discount() == Decimal("5.00")


def test_calculate_bulk_discount_rounding_half_up():
    item = LineItem("apple", Decimal("0.13"), 10)
    assert item.calculate_bulk_discount() == Decimal("0.13")


def test_calculate_bulk_discount_exact_threshold():
    item = LineItem("apple", Decimal("1.00"), 10)
    assert item.calculate_bulk_discount() == Decimal("0.10")
